package akogen.fabric.v6;
import java.nio.file.*;import java.util.concurrent.atomic.*;import java.util.*;
public class ObserveGamePublication {public static void main(String[]args)throws Exception{String channel=new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8").trim(),catalog=SyncCodec.hash(Files.readAllBytes(Paths.get(args[1]))).substring(0,24);AtomicInteger seen=new AtomicInteger();MqttLink link=new MqttLink("broker.emqx.io",8883,(topic,body)->{try{SyncCodec.State s=SyncCodec.decode(body,catalog);if(!s.clear){for(int id:s.ids)if(id<0||id>47)throw new AssertionError("Unknown ID");seen.incrementAndGet();}}catch(Exception error){throw new RuntimeException(error);}});try{link.open();link.subscriptions(Collections.singleton(channel));long until=System.currentTimeMillis()+12000;while(System.currentTimeMillis()<until&&seen.get()==0)link.poll();if(seen.get()==0)throw new AssertionError("No publication from live game");System.out.println("PASS real Minecraft instance publishes valid appearance snapshots over trusted TLS; own exact channel only");}finally{link.close();}}}
